def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    bg = max(counts, key=counts.get)

    occupied = {
        (r, c): grid[r][c]
        for r in range(h) for c in range(w)
        if grid[r][c] != bg
    }
    if not occupied:
        return [row[:] for row in grid]

    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
    dr, dc = max(
        directions,
        key=lambda d: sum(
            (r + d[0], c + d[1]) in occupied for r, c in occupied
        )
    )

    stripes = {}
    for (r, c), color in occupied.items():
        if (dr, dc) == (0, 1):
            key, t = r, c
        elif (dr, dc) == (1, 0):
            key, t = c, r
        elif (dr, dc) == (1, 1):
            key, t = r - c, r
        else:
            key, t = r + c, r
        stripes.setdefault(key, {})[t] = color

    def runs_for(line):
        ts = sorted(line)
        runs = []
        run = [ts[0]]
        for t in ts[1:]:
            if t == run[-1] + 1:
                run.append(t)
            else:
                runs.append(run)
                run = [t]
        runs.append(run)
        return runs

    keys = sorted(stripes)
    anchor_runs = runs_for(stripes[keys[len(keys) // 2]])
    target_len = max(map(len, anchor_runs))

    # Extend/truncate toward the side most commonly shared by the segments.
    starts, ends = {}, {}
    for line in stripes.values():
        for run in runs_for(line):
            starts[run[0]] = starts.get(run[0], 0) + 1
            ends[run[-1]] = ends.get(run[-1], 0) + 1
    start_score = max(starts.values())
    end_score = max(ends.values())
    align_start = start_score > end_score

    out = [[bg] * w for _ in range(h)]
    for key, line in stripes.items():
        for run in runs_for(line):
            color = line[run[0]]
            if align_start:
                ts = range(run[0], run[0] + target_len)
            else:
                ts = range(run[-1] - target_len + 1, run[-1] + 1)

            for t in ts:
                if (dr, dc) == (0, 1):
                    r, c = key, t
                elif (dr, dc) == (1, 0):
                    r, c = t, key
                elif (dr, dc) == (1, 1):
                    r, c = t, t - key
                else:
                    r, c = t, key - t
                if 0 <= r < h and 0 <= c < w:
                    out[r][c] = color

    return out
